@namespace sv_11a1bb1933d947a4b1362f34f886e76d.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var cssClass = step == CurrentStep ? "step active"
                         : CompletedSteps.Contains(step) ? "step completed"
                         : "step dimmed";
            <li class="@cssClass">
                @if (CompletedSteps.Contains(step))
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@StepNames[step - 1]</span>
                    </button>
                }
                else
                {
                    <span class="step-content">
                        <span class="step-icon">@step</span>
                        <span class="step-label">@StepNames[step - 1]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

@namespace sv_11a1bb1933d947a4b1362f34f886e76d.Components.Pages.Apply

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name</label>
            <input type="text" value="@Company" @onchange="e => UpdateField(() => Company = e.Value?.ToString() ?? string.Empty)" />
        </div>
        <div class="form-group">
            <label>Job Title</label>
            <input type="text" value="@Title" @onchange="e => UpdateField(() => Title = e.Value?.ToString() ?? string.Empty)" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => UpdateField(() => StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")))" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            @if (!IsCurrent)
            {
                <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)" @onchange="e => UpdateField(() => EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!))" />
            }
            else
            {
                <input type="date" disabled value="" />
            }
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => UpdateField(() => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; })" />
                Currently working here
            </label>
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="e => UpdateField(() => Description = e.Value?.ToString() ?? string.Empty)"></textarea>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter] public string Company { get; set; } = string.Empty;
    [Parameter] public string Title { get; set; } = string.Empty;
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = string.Empty;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private void UpdateField(Action update)
    {
        update();
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

@namespace sv_11a1bb1933d947a4b1362f34f886e76d.Components.Pages.Apply

<div class="reference-form">
    <div class="form-row">
        <div class="form-group">
            <label>Name</label>
            <input type="text" value="@Name" @onchange="e => UpdateField(() => Name = e.Value?.ToString() ?? string.Empty)" />
        </div>
        <div class="form-group">
            <label>Relationship</label>
            <input type="text" value="@Relationship" @onchange="e => UpdateField(() => Relationship = e.Value?.ToString() ?? string.Empty)" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Email</label>
            <input type="email" value="@Email" @onchange="e => UpdateField(() => Email = e.Value?.ToString() ?? string.Empty)" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Phone" @onchange="e => UpdateField(() => Phone = e.Value?.ToString() ?? string.Empty)" />
        </div>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter] public string Name { get; set; } = string.Empty;
    [Parameter] public string Relationship { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }

    private void UpdateField(Action update)
    {
        update();
        OnChanged.InvokeAsync(new ReferenceData(Name, Relationship, Email, Phone));
    }

    public record ReferenceData(string Name, string Relationship, string Email, string Phone);
}

@namespace sv_11a1bb1933d947a4b1362f34f886e76d.Components.Pages.Apply

<div class="step-content-panel">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label>Full Name <span class="required">*</span></label>
        <input type="text" value="@FullName" @onchange="e => FullName = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Email <span class="required">*</span></label>
        <input type="email" value="@Email" @onchange="e => Email = e.Value?.ToString() ?? string.Empty" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone <span class="required">*</span></label>
        <input type="tel" value="@Phone" @onchange="e => Phone = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label>Address <span class="required">*</span></label>
        <textarea rows="2" value="@Address" @onchange="e => Address = e.Value?.ToString() ?? string.Empty"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ValidationError;
    private string? EmailError;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ValidationError = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ValidationError = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            if (ValidateEmail is not null)
            {
                var isValid = await ValidateEmail(Email);
                if (!isValid)
                {
                    EmailError = "Please enter a valid email address.";
                    return;
                }
            }

            await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
        }
        finally
        {
            IsValidating = false;
        }
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

@namespace sv_11a1bb1933d947a4b1362f34f886e76d.Components.Pages.Apply

<div class="step-content-panel">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];
        <div class="entry-card">
            <h3>Position @(index + 1)</h3>
            <WorkEntryForm
                Company="@entry.Company"
                Title="@entry.Title"
                StartDate="@entry.StartDate"
                EndDate="@entry.EndDate"
                IsCurrent="@entry.IsCurrent"
                Description="@entry.Description"
                CanRemove="@(Entries.Count > 1)"
                OnRemove="() => RemoveEntry(index)"
                OnChanged="data => UpdateEntry(index, data)" />
        </div>
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<EntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<EntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private void AddEntry()
    {
        Entries.Add(new EntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryData data)
    {
        Entries[index] = new EntryModel
        {
            Company = data.Company,
            Title = data.Title,
            StartDate = data.StartDate,
            EndDate = data.EndDate,
            IsCurrent = data.IsCurrent,
            Description = data.Description
        };
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(Entries);
    }

    public class EntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

@namespace sv_11a1bb1933d947a4b1362f34f886e76d.Components.Pages.Apply

<div class="step-content-panel">
    <h2>References</h2>

    @for (int i = 0; i < References.Count; i++)
