@namespace sv_11a1bb1933d947a4b1362f34f886e76d.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var cssClass = step == CurrentStep ? "step active"
                         : CompletedSteps.Contains(step) ? "step completed"
                         : "step dimmed";
            <li class="@cssClass">
                @if (CompletedSteps.Contains(step))
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@StepNames[step - 1]</span>
                    </button>
                }
                else
                {
                    <span class="step-content">
                        <span class="step-icon">@step</span>
                        <span class="step-label">@StepNames[step - 1]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
