arguments.file_text:
@page "/apply"
@namespace sv_11a1bb1933d947a4b1362f34f886e76d.Components.Pages.Apply
@using sv_11a1bb1933d947a4b1362f34f886e76d.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@_currentStep" CompletedSteps="@_completedSteps" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 1:
            <PersonalInfoStep
                FullName="@_fullName"
                Email="@_email"
                Phone="@_phone"
                Address="@_address"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalInfoNext" />
            break;

        case 2:
            <WorkHistoryStep
                Entries="@_workEntries"
                OnNext="HandleWorkHistoryNext"
                OnBack="() => GoToStep(1)" />
            break;

        case 3:
            <ReferencesStep
                References="@_references"
                OnNext="HandleReferencesNext"
                OnBack="() => GoToStep(2)" />
            break;

        case 4:
            <CoverLetterStep
                CoverLetter="@_coverLetter"
                OnNext="HandleCoverLetterNext"
                OnBack="() => GoToStep(3)" />
            break;

        case 5:
            <ReviewStep
                FullName="@_fullName"
                Email="@_email"
                Phone="@_phone"
                Address="@_address"
                WorkEntries="@_workEntries.Select(e => new ReviewStep.WorkEntryInfo(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()"
                References="@_references.Select(r => new ReviewStep.ReferenceInfo(r.Name, r.Relationship, r.Email, r.Phone)).ToList()"
                CoverLetter="@_coverLetter"
                OnEditStep="GoToStep"
                OnBack="() => GoToStep(4)"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep = 1;
    private HashSet<int> _completedSteps = new();

    // Step 1 data
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 data
    private List<WorkHistoryStep.EntryModel> _workEntries = new() { new() };

    // Step 3 data
    private List<ReferencesStep.ReferenceModel> _references = new() { new(), new() };

    // Step 4 data
    private string _coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (step <= _currentStep || _completedSteps.Contains(step))
            _currentStep = step;
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        _fullName = result.FullName;
        _email = result.Email;
        _phone = result.Phone;
        _address = result.Address;
        _completedSteps.Add(1);
        _currentStep = 2;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.EntryModel> entries)
    {
        _workEntries = entries;
        _completedSteps.Add(2);
        _currentStep = 3;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> references)
    {
        _references = references;
        _completedSteps.Add(3);
        _currentStep = 4;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _completedSteps.Add(4);
        _currentStep = 5;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(_fullName, _email, _phone, _address),
            new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
    position: relative;
}

.step-list::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 0;
    right: 0;
    height: 2px;
    background: #e0e0e0;
    z-index: 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    z-index: 1;
    background: white;
    padding: 0 0.5rem;
}

.step-button, .step-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    border: none;
    background: none;
    cursor: default;
    padding: 0;
    font: inherit;
}

.step-button {
    cursor: pointer;
}

.step-icon {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    margin-bottom: 0.25rem;
}

.step.active .step-icon {
    background: #4361ee;
    color: white;
}

.step.completed .step-icon {
    background: #2ecc71;
    color: white;
}

.step.dimmed .step-icon {
    background: #e0e0e0;
    color: #999;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
}

.step.dimmed .step-label {
    color: #999;
}

/* Form Styles */
.step-content-panel {
    background: #f8f9fa;
    border-radius: 8px;
    padding: 2rem;
    border: 1px solid #e9ecef;
}

.step-content-panel h2 {
    margin-top: 0;
    color: #1a1a2e;
    border-bottom: 2px solid #4361ee;
    padding-bottom: 0.5rem;
    margin-bottom: 1.5rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    color: #333;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.required {
    color: #e74c3c;
}

.field-error {
    color: #e74c3c;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

.validation-error {
    background: #ffeaea;
    color: #c0392b;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    border: 1px solid #f5c6cb;
}

.checkbox-label {
