@page "/apply"
@namespace sv_11a1bb1933d947a4b1362f34f886e76d.Components.Pages.Apply
@using sv_11a1bb1933d947a4b1362f34f886e76d.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@_currentStep" CompletedSteps="@_completedSteps" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 1:
            <PersonalInfoStep
                FullName="@_fullName"
                Email="@_email"
                Phone="@_phone"
                Address="@_address"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalInfoNext" />
            break;

        case 2:
            <WorkHistoryStep
                Entries="@_workEntries"
                OnNext="HandleWorkHistoryNext"
                OnBack="() => GoToStep(1)" />
            break;

        case 3:
            <ReferencesStep
                References="@_references"
                OnNext="HandleReferencesNext"
                OnBack="() => GoToStep(2)" />
            break;

        case 4:
            <CoverLetterStep
                CoverLetter="@_coverLetter"
                OnNext="HandleCoverLetterNext"
                OnBack="() => GoToStep(3)" />
            break;

        case 5:
            <ReviewStep
                FullName="@_fullName"
                Email="@_email"
                Phone="@_phone"
                Address="@_address"
                WorkEntries="@_workEntries.Select(e => new ReviewStep.WorkEntryInfo(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()"
                References="@_references.Select(r => new ReviewStep.ReferenceInfo(r.Name, r.Relationship, r.Email, r.Phone)).ToList()"
                CoverLetter="@_coverLetter"
                OnEditStep="GoToStep"
                OnBack="() => GoToStep(4)"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep = 1;
    private HashSet<int> _completedSteps = new();

    // Step 1 data
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 data
    private List<WorkHistoryStep.EntryModel> _workEntries = new() { new() };

    // Step 3 data
    private List<ReferencesStep.ReferenceModel> _references = new() { new(), new() };

    // Step 4 data
    private string _coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (step <= _currentStep || _completedSteps.Contains(step))
            _currentStep = step;
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        _fullName = result.FullName;
        _email = result.Email;
        _phone = result.Phone;
        _address = result.Address;
        _completedSteps.Add(1);
        _currentStep = 2;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.EntryModel> entries)
    {
        _workEntries = entries;
        _completedSteps.Add(2);
        _currentStep = 3;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> references)
    {
        _references = references;
        _completedSteps.Add(3);
        _currentStep = 4;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _completedSteps.Add(4);
        _currentStep = 5;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(_fullName, _email, _phone, _address),
            new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

