    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.entry-card h3 {
    margin: 0 0 1rem 0;
    font-size: 1rem;
    color: #555;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px;
    resize: vertical;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

/* Review Step */
