    {
        Relationship = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void HandleEmailChanged(ChangeEventArgs e)
    {
        Email = e.Value?.ToString() ?? string.Empty;
        NotifyChanged();
    }

    private void HandlePhoneChanged(ChangeEventArgs e)
    {
