@namespace sv_11a1bb1933d947a4b1362f34f886e76d.Components.Pages.Apply

<div class="step-content-panel">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label>Full Name <span class="required">*</span></label>
        <input type="text" value="@FullName" @onchange="HandleFullNameChanged" />
    </div>

    <div class="form-group">
        <label>Email <span class="required">*</span></label>
        <input type="email" value="@Email" @onchange="HandleEmailChanged" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone <span class="required">*</span></label>
        <input type="tel" value="@Phone" @onchange="HandlePhoneChanged" />
    </div>

    <div class="form-group">
        <label>Address <span class="required">*</span></label>
        <textarea rows="2" value="@Address" @onchange="HandleAddressChanged"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ValidationError;
    private string? EmailError;
    private bool IsValidating;

    private void HandleFullNameChanged(ChangeEventArgs e) => FullName = e.Value?.ToString() ?? string.Empty;
    private void HandleEmailChanged(ChangeEventArgs e) => Email = e.Value?.ToString() ?? string.Empty;
    private void HandlePhoneChanged(ChangeEventArgs e) => Phone = e.Value?.ToString() ?? string.Empty;
    private void HandleAddressChanged(ChangeEventArgs e) => Address = e.Value?.ToString() ?? string.Empty;

    private async Task HandleNext()
    {
        ValidationError = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ValidationError = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            if (ValidateEmail is not null)
            {
                var isValid = await ValidateEmail(Email);
                if (!isValid)
                {
                    EmailError = "Please enter a valid email address.";
                    return;
                }
            }

            await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
        }
        finally
        {
            IsValidating = false;
        }
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

